export function collides(a, b) {
  const dx = a.x - b.x;
  const dy = a.y - b.y;
  return Math.hypot(dx, dy) <= a.radius + b.radius;
}

import { collides } from './collision.js';

export function hitOutcome(shot, asteroid) {
  if (!collides(shot, asteroid)) return { score: 0, asteroids: [asteroid] };
  return { score: 100, asteroids: [] };
}

function minimumImage(delta, span) {
  return Math.min(Math.abs(delta), span - Math.abs(delta));
}

export function collides(a, b, world = { width: 640, height: 360 }) {
  const dx = minimumImage(a.x - b.x, world.width);
  const dy = minimumImage(a.y - b.y, world.height);
  return Math.hypot(dx, dy) <= a.radius + b.radius;
}

