import test from 'node:test';
import assert from 'node:assert/strict';
import { collides } from '../src/collision.js';

const world = { width: 640, height: 360 };

test('registers a hit across the wrapped x edge', () => {
  assert.equal(collides({ x: 636, y: 180, radius: 3 }, { x: 8, y: 180, radius: 10 }, world), true);
});

test('keeps separated center objects apart', () => {
  assert.equal(collides({ x: 100, y: 100, radius: 3 }, { x: 200, y: 100, radius: 10 }, world), false);
});

