import { collides } from './collision.js';

function fragmentsFor(asteroid) {
  if (asteroid.radius <= 12) return [];
  const radius = Number((asteroid.radius * 0.58).toFixed(2));
  return [-1, 1].map((direction, index) => ({ ...asteroid, id: `fragment-${10 + index}`, radius, vx: direction * 70, vy: 45 }));
}

export function hitOutcome(shot, asteroid, world) {
  if (!collides(shot, asteroid, world)) return { score: 0, asteroids: [asteroid] };
  return { score: 100, asteroids: fragmentsFor(asteroid) };
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { hitOutcome } from '../src/game.js';

test('splits one radius-32 asteroid deterministically', () => {
  const result = hitOutcome({ x: 636, y: 180, radius: 3 }, { id: 'rock', x: 8, y: 180, radius: 32 }, { width: 640, height: 360 });
  assert.equal(result.score, 100);
  assert.deepEqual(result.asteroids.map(a => [a.id, a.radius]), [['fragment-10', 18.56], ['fragment-11', 18.56]]);
});

import test from 'node:test';
import assert from 'node:assert/strict';
import { hitOutcome } from '../src/game.js';

const world = { width: 640, height: 360 };

test('splits one radius-32 asteroid deterministically', () => {
  const result = hitOutcome({ x: 636, y: 180, radius: 3 }, { id: 'rock', x: 8, y: 180, radius: 32 }, world);
  assert.deepEqual(result.asteroids.map(a => [a.id, a.radius]), [['fragment-10', 18.56], ['fragment-11', 18.56]]);
});

test('removes a size-1 asteroid without fragments', () => {
  const result = hitOutcome({ x: 636, y: 180, radius: 3 }, { id: 'tiny', x: 8, y: 180, radius: 1 }, world);
  assert.deepEqual(result.asteroids, []);
});
